 @Test void realMysqlLockBusyIsHttp503WithNoPartialRepair()throws Exception{F f=fixture();assign(f,techA,0);try(var c=Objects.requireNonNull(jdbc.getDataSource()).getConnection()){c.setAutoCommit(false);try(var st=c.prepareStatement("SELECT id FROM drone WHERE id=? FOR UPDATE")){st.setLong(1,f.device);try(var r=st.executeQuery()){assertTrue(r.next());}}call("/workbench/tickets/"+f.ticket+"/start","POST",null,techA,503,label());assertEquals(0,n("SELECT status FROM maintenance_ticket WHERE id=?",f.ticket));gold(f);c.rollback();}fact("real_http503",Map.of("ticket",f.ticket));}
 @Test void techniciansAreCreatedAsRealRoleAndCredentialsNeverReturned()throws Exception{var data=call("/admin/technicians","POST",Map.of("username","t_"+UUID.randomUUID().toString().substring(0,8),"password","Synthetic-test-123!"),admin,200,null);assertTrue(data.get("id").isTextual());assertFalse(data.has("password"));long id=Long.parseLong(data.get("id").asText());assertEquals(2,n("SELECT role FROM user WHERE id=?",id));assertTrue(jdbc.queryForObject("SELECT password FROM user WHERE id=?",String.class,id).startsWith("$2"));call("/admin/technicians","POST",Map.of("username","bad","password","weak"),admin,400,null);call("/admin/technicians","POST",Map.of("username","notallowed","password","Synthetic-test-123!"),techA,403,null);}
